// ==========================================
// 🚗 VIN დეკოდერის ფუნქციონალი (Octane App)
// ==========================================

const BRAND_DB = {
    'WBA': { name: 'BMW' },
    'WBS': { name: 'BMW M' },
    'WDB': { name: 'Mercedes-Benz' },
    'WDD': { name: 'Mercedes-Benz' },
    'WAU': { name: 'Audi' },
    'WVW': { name: 'Volkswagen' },
    'JTJ': { name: 'Lexus' },
    'JTE': { name: 'Toyota' },
    '4T1': { name: 'Toyota' },
    '1FA': { name: 'Ford' },
    '5YJ': { name: 'Tesla' }
};

const YEAR_CODES = {
    '1': 2001, '2': 2002, '3': 2003, '4': 2004, '5': 2005, '6': 2006, '7': 2007, '8': 2008, '9': 2009,
    'A': 2010, 'B': 2011, 'C': 2012, 'D': 2013, 'E': 2014, 'F': 2015, 'G': 2016, 'H': 2017, 'J': 2018,
    'K': 2019, 'L': 2020, 'M': 2021, 'N': 2022, 'P': 2023, 'R': 2024, 'S': 2025, 'T': 2026
};

async function decodeVIN(vinCode) {
    // თუ VIN არ არსებობს, ცარიელია ან NO DATA-ს აბრუნებს
    if (!vinCode || vinCode.includes('NO DATA') || vinCode.length < 11) {
        return {
            success: false,
            message: 'VIN კოდის დაფიქსირება შეუძლებელია, რადგან მანქანის სისტემაში კოდი ჩაწერილი არ არის.'
        };
    }

    const cleanVin = vinCode.trim().toUpperCase();
    const wmi = cleanVin.substring(0, 3);
    const yearChar = cleanVin.charAt(9);

    let brandInfo = BRAND_DB[wmi] || { name: 'უცნობი მარკა' };
    let estimatedYear = YEAR_CODES[yearChar] || 'უცნობი წელი';

    try {
        const response = await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/decodevinvalues/${cleanVin}?format=json`);
        const data = await response.json();
        
        if (data.Results && data.Results[0]) {
            const res = data.Results[0];
            return {
                success: true,
                vin: cleanVin,
                make: res.Make || brandInfo.name,
                model: res.Model || 'მოდელი უცნობია',
                year: res.ModelYear || estimatedYear,
                engine: res.DisplacementL ? `${res.DisplacementL}L` : 'ნ/ა'
            };
        }
    } catch (e) {
        console.log("API Error, falling back to local decoder", e);
    }

    return {
        success: true,
        vin: cleanVin,
        make: brandInfo.name,
        model: 'მოდელი უცნობია (Offline)',
        year: estimatedYear,
        engine: 'ნ/ა'
    };
}